export const WORK_ITEMS = WORK_DB.work_items || [];
export const WORK_ITEM_DETAILS = WORK_DB.work_item_details || {};
export const DB_SOURCES = WORK_DB.sources || [];

export function normalizeWorkName(item) {
  if (!item) return "";
  return item.세부작업 || item.name || "";
}

export function getWorkIdByName(name) {
  const hit = WORK_ITEMS.find(item => normalizeWorkName(item) === name || `${item.중공종} ${item.세부작업}` === name);
  return hit?.작업ID || null;
}

export function getWorkItemByName(name) {
  const id = getWorkIdByName(name);
  return id ? WORK_ITEM_DETAILS[id]?.work_item || WORK_ITEMS.find(item => item.작업ID === id) : null;
}

export function getWorkDetailByName(name) {
  const id = getWorkIdByName(name);
  return id ? WORK_ITEM_DETAILS[id] : null;
}

export function getWorkDetailById(id) {
  return WORK_ITEM_DETAILS[id] || null;
}

export function getTradeGroups() {
  const byCat = new Map();
  WORK_ITEMS.forEach(item => {
    const cat = item.대공종 || "기타";
    if (!byCat.has(cat)) byCat.set(cat, []);
    byCat.get(cat).push({
      id: item.작업ID,
      name: item.세부작업,
      middle: item.중공종,
      category: item.대공종,
      baseRisk: item.기본위험도,
      keywords: item.검색키워드 || ""
    });
  });
  return Array.from(byCat.entries()).map(([category, items]) => ({
    category,
    items: items.sort((a,b)=>String(a.name).localeCompare(String(b.name),'ko'))
  })).sort((a,b)=>String(a.category).localeCompare(String(b.category),'ko'));
}

export const TRADE_GROUPS = getTradeGroups();

export function searchWorkItems(keyword) {
  const q = String(keyword || '').trim().toLowerCase();
  if (!q) return WORK_ITEMS;
  return WORK_ITEMS.filter(item => {
    const hay = `${item.대공종} ${item.중공종} ${item.세부작업} ${item.검색키워드}`.toLowerCase();
    return hay.includes(q);
  });
}

export function riskRank(level) {
  const map = {"낮음":1,"보통":2,"중":3,"상":4,"매우상":5,"매우 높음":5};
  return map[level] || 2;
}

export function uniqueByText(items) {
  const seen = new Set();
  return items.filter(item => {
    const text = typeof item === 'string' ? item : (item.text || item.체크문항 || item.title || JSON.stringify(item));
    if (seen.has(text)) return false;
    seen.add(text);
    return true;
  });
}
